#include <iostream>
using namespace std;

template <typename... Args>
int countAll(Args... args) {
    return sizeof...(args);
}

template <typename... Args>
int addAll(Args... args) {
    return (args + ... + 0);
}

template <typename... Args>
void printAll(Args... args) {
    (cout << ... << args);
    cout << endl;
}

int main() {
    int n = 0;
    cin >> n;

    cout << "样数 " << countAll(n, 7, 3) << endl;
    cout << "全部 " << addAll(n, 7, 3) << endl;
    printAll("连写 ", n, 7, 3);
    return 0;
}

